import novamind_api as nm

print('Day:', nm.vars.current_day)

# R&D projects
print('\n--- R&D Projects ---')
projects = nm.research.list_research_projects()
print(type(projects))
if isinstance(projects, dict):
    for k, v in projects.items():
        print(f'  {k}: {v}')
elif isinstance(projects, list):
    for p in projects:
        if isinstance(p, dict):
            print(f'  {p}')
        else:
            print(f'  {p}')
else:
    print(f'  Raw: {projects}')

# Get cost info
print('\n--- Cost Info ---')
cost = nm.infrastructure.get_cost_info()
print(type(cost))
if isinstance(cost, dict):
    for k, v in cost.items():
        print(f'  {k}: {v}')

# S2 insights - estimates
print('\n--- S2 Estimates ---')
s2 = nm.market.get_group_insights(group_id='S2')
if 'estimates' in s2:
    print(f'  estimates: {s2[\"estimates\"]}')
if 'info_level' in s2:
    print(f'  info_level: {s2[\"info_level\"]}')
if 'noise' in s2:
    print(f'  noise: {s2[\"noise\"]}')

# S3 estimates
print('\n--- S3 Estimates ---')
s3 = nm.market.get_group_insights(group_id='S3')
if 'estimates' in s3:
    print(f'  estimates: {s3[\"estimates\"]}')
if 'info_level' in s3:
    print(f'  info_level: {s3[\"info_level\"]}')
if 'noise' in s3:
    print(f'  noise: {s3[\"noise\"]}')

# List daily scripts
print('\n--- Daily Scripts ---')
import os
if os.path.exists('weekly_scripts'):
    for f in os.listdir('weekly_scripts'):
        print(f'  {f}')
else:
    print('  No weekly_scripts dir')
" 2>&1

